import{_ as t,c as a,o as s,ax as i}from"./chunks/framework.DHqKNX4U.js";const m=JSON.parse('{"title":"System Settings","description":"","frontmatter":{},"headers":[],"relativePath":"user-guides/settings/system.md","filePath":"user-guides/settings/system.md"}'),o={name:"user-guides/settings/system.md"};function r(n,e,l,d,h,u){return s(),a("div",null,e[0]||(e[0]=[i('<h1 id="system-settings" tabindex="-1">System Settings <a class="header-anchor" href="#system-settings" aria-label="Permalink to &quot;System Settings&quot;">​</a></h1><p>System settings allow administrators to configure the global look and theme of the application. These settings apply to all users.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h3><p>This setting determines the default display language for the application UI. The selected language will be used for all interface elements, including menus, labels, and messages.</p><blockquote><p><strong>Important:</strong> When the language is changed, the backend (API) language will only change after a restart of the server. The frontend will update immediately.</p></blockquote><p>Supported languages:</p><ul><li>English</li><li>German</li><li>French</li><li>Estonian</li><li>Spanish</li><li>Italian</li><li>Portuguese</li><li>Dutch</li><li>Greek</li><li>Japanese</li></ul><h3 id="date-format" tabindex="-1">Date Format <a class="header-anchor" href="#date-format" aria-label="Permalink to &quot;Date Format&quot;">​</a></h3><p>This setting controls how dates and times are shown to every user across the application, including the archive, search results, email details and the audit log.</p><table tabindex="0"><thead><tr><th>Option</th><th>Example</th></tr></thead><tbody><tr><td>Follow the language setting (default)</td><td>The conventions of the language selected above</td></tr><tr><td>ISO 8601</td><td><code>2026-10-14</code>, and <code>2026-10-14T10:00:00+02:00</code> with the time</td></tr><tr><td>European</td><td><code>14/10/2026 10:00:00</code></td></tr><tr><td>US</td><td><code>10/14/2026 10:00:00</code></td></tr></tbody></table><p>Times are shown in each viewer&#39;s own time zone. The ISO 8601 option also shows the UTC offset, so an audit entry or email timestamp can be compared exactly by reviewers in different time zones. A preview under the setting shows the current time in the selected format before you save.</p><h3 id="default-theme" tabindex="-1">Default Theme <a class="header-anchor" href="#default-theme" aria-label="Permalink to &quot;Default Theme&quot;">​</a></h3><p>This setting controls the default color theme for the application. Users can choose between light, dark, or system default. The system default theme will sync with the user&#39;s operating system theme.</p><h3 id="support-email" tabindex="-1">Support Email <a class="header-anchor" href="#support-email" aria-label="Permalink to &quot;Support Email&quot;">​</a></h3><p>This setting allows administrators to provide a public-facing email address for user support inquiries. This email address may be displayed on error pages or in other areas where users may need to contact support.</p>',16)]))}const p=t(o,[["render",r]]);export{m as __pageData,p as default};
